#include "forge/board.hpp"
#include <fstream>
#include <iostream>
#include <optional>
#include <sstream>
#include <string>
std::string q(const std::string&s){std::string r="\"";for(char c:s){if(c=='"'||c=='\\')r+='\\';r+=c;}return r+'"';}
const char* b(bool x){return x?"true":"false";}
void position(const std::string&label,int ply,const forge::Board&board){const auto legal=board.legal_moves();std::cout<<"{\"type\":\"position\",\"line\":"<<q(label)<<",\"ply\":"<<ply<<",\"fen\":"<<q(board.fen())<<",\"halfmoveClock\":"<<board.halfmove_clock()<<",\"sideToMove\":"<<q(board.side_to_move()==forge::White?"white":"black")<<",\"inCheck\":"<<b(board.in_check())<<",\"legalMoves\":"<<legal.size()<<",\"checkmate\":"<<b(legal.empty()&&board.in_check())<<",\"stalemate\":"<<b(legal.empty()&&!board.in_check())<<",\"fiftyMoveThreshold\":"<<b(board.halfmove_clock()>=100)<<",\"threefold\":"<<b(board.is_repetition())<<",\"insufficientMaterial\":"<<b(board.is_insufficient_material())<<"}\n";}
int main(int argc,char**argv){if(argc!=2)return 2;std::ifstream input(argv[1]);std::string fen,line;std::getline(input,fen);if(!input)return 3;while(std::getline(input,line)){if(line.empty())continue;std::istringstream moves(line);std::string label,uci;moves>>label;forge::Board board;std::string error;if(!board.set_fen(fen,&error)){std::cerr<<error;return 4;}position(label,0,board);int ply=0;while(moves>>uci){const auto legal=board.legal_moves();std::optional<forge::Move> chosen;for(const auto move:legal)if(forge::Board::move_to_uci(move)==uci)chosen=move;std::cout<<"{\"type\":\"move\",\"line\":"<<q(label)<<",\"ply\":"<<++ply<<",\"uci\":"<<q(uci)<<",\"legal\":"<<b(chosen.has_value());if(!chosen){std::cout<<"}\n";return 5;}const auto captured=board.captured_piece(*chosen);const auto mover=board.moved_piece(*chosen);const int before=board.halfmove_clock();forge::Undo undo;if(!board.make_move(*chosen,undo))return 6;const std::string pieces=".PNBRQKpnbrqk";std::cout<<",\"movedPiece\":"<<q(std::string(1,pieces[mover]))<<",\"capturedPiece\":"<<q(std::string(1,pieces[captured]))<<",\"capture\":"<<b(captured!=forge::Empty)<<",\"clockBefore\":"<<before<<",\"clockAfter\":"<<board.halfmove_clock()<<"}\n";position(label,ply,board);}const auto legal=board.legal_moves();std::cout<<"{\"type\":\"final\",\"line\":"<<q(label)<<",\"plies\":"<<ply<<",\"fen\":"<<q(board.fen())<<",\"halfmoveClock\":"<<board.halfmove_clock()<<",\"inCheck\":"<<b(board.in_check())<<",\"legalMoves\":"<<legal.size()<<",\"checkmate\":"<<b(legal.empty()&&board.in_check())<<"}\n";}return 0;}
